// Junta las 3 pestañas, ordena por fecha y hora (más reciente primero) y devuelve las últimas N.
// Tolerante al formato: Google Sheets puede devolver la fecha como 'YYYY-MM-DD',
// como 'DD/MM/YYYY' o como número de serie, según cómo haya formateado la celda.
const q = ($('Últimos Registros').first().json.query) || {};
const N = Math.min(50, Math.max(1, parseInt(q.n, 10) || 5));

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && r.id); } catch (e) { return []; }
}
function pad(n) { return String(n).padStart(2, '0'); }
function claveFecha(f) {
  if (f === null || f === undefined || f === '') return '';
  if (typeof f === 'number') {
    const d = new Date(Math.round((f - 25569) * 86400000));
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }
  const s = String(f).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return m[1] + '-' + pad(m[2]) + '-' + pad(m[3]);
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[3] + '-' + pad(m[2]) + '-' + pad(m[1]);
  return s;
}
function claveHora(h) {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    const seg = Math.round((h % 1) * 86400);
    return pad(Math.floor(seg / 3600)) + ':' + pad(Math.floor((seg % 3600) / 60));
  }
  const m = String(h).trim().match(/^(\d{1,2}):(\d{2})/);
  return m ? pad(m[1]) + ':' + m[2] : String(h);
}
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.'));
  return isFinite(n) ? n : null;
}

const reg = [];
filas('Leer Lactancia').forEach(r => reg.push({ tipo: 'lactancia', id: r.id, fecha: claveFecha(r.fecha), hora: claveHora(r.hora_inicio), hora_fin: claveHora(r.hora_fin), duracion_min: num(r.duracion_min), detalle: r.tipo || '', onzas: num(r.onzas), estado: r.estado || '', _fila: r.row_number || 0 }));
filas('Leer Sueño').forEach(r => reg.push({ tipo: 'sueno', id: r.id, fecha: claveFecha(r.fecha), hora: claveHora(r.hora_inicio), hora_fin: claveHora(r.hora_fin), duracion_min: num(r.duracion_min), detalle: '', onzas: null, estado: r.estado || '', _fila: r.row_number || 0 }));
filas('Leer Pañales').forEach(r => reg.push({ tipo: 'panal', id: r.id, fecha: claveFecha(r.fecha), hora: claveHora(r.hora), hora_fin: '', duracion_min: null, detalle: r.contenido || '', onzas: null, estado: '', _fila: r.row_number || 0 }));

reg.sort((a, b) => (b.fecha + b.hora).localeCompare(a.fecha + a.hora) || (b._fila - a._fila));

function abierto(tipo) {
  const r = reg.find(x => x.tipo === tipo && x.estado === 'En curso');
  return r ? { id: r.id, fecha: r.fecha, hora: r.hora } : null;
}

return [{ json: {
  ok: true,
  total: reg.length,
  en_curso: { lactancia: abierto('lactancia'), sueno: abierto('sueno') },
  registros: reg.slice(0, N).map(({ _fila, ...r }) => r)
} }];
